import random, sys, time
sys.path.insert(0, '/workspace/submission')
import compiler

random.seed(11)
N = 48
PARTS = list(range(32))
ORD = list(range(32, 48))
links = []; seen = set()
def add(u, v):
    key = (min(u, v), max(u, v))
    if key in seen or u == v: return
    seen.add(key); links.append((u, v))
for i in range(len(ORD)):
    add(ORD[i], ORD[(i + 1) % len(ORD)])
for p in PARTS:
    for k in range(4):
        add(p, ORD[(p * (k + 1) + 3 * k) % len(ORD)])
demands = {p: random.randrange(1, 6) for p in PARTS}
envelope = {i: 20 for i in range(len(links))}
period = 4
caps = {l: period * r for l, r in envelope.items()}
adj = compiler._adjacency(N, links, envelope)
ordinary = set(range(N)) - set(PARTS)
reach = {}
for u in PARTS:
    parent, _ = compiler._bfs_tree(adj, u, ordinary)
    reach[u] = [w for w in parent if w in PARTS and w != u]
trees, logical = compiler._logical_trees(PARTS, demands, reach, 'relay')
print('D', sum(demands.values()))
residual = {}
for l, c in caps.items():
    residual[(l, 0)] = c; residual[(l, 1)] = c
pairs = sorted(logical.items(), key=lambda kv: (-kv[1], kv[0]))
loads = {}
for (u, v), demand in pairs:
    need = demand
    while need > 0:
        chain, room = compiler._widest_path(adj, u, v, ordinary, residual)
        if chain is None:
            print('NO PATH', u, v, 'need', need)
            break
        take = min(need, room)
        for l, d in chain:
            residual[(l, d)] -= take
            loads[(l, d)] = loads.get((l, d), 0) + take
        need -= take
    else:
        continue
    break
print('max load', max(loads.values()), 'cap', caps[max(loads, key=lambda k: loads[k])])
over = [(k, v) for k, v in loads.items() if v > caps[k[0]]]
print('overloaded', over[:10])
tot = sum(loads.values())
print('total traversals', tot, 'total capacity', sum(2 * c for c in caps.values()))
PYEOF
